import { useId, type ComponentProps, type ReactNode } from "react";

import { spokenDuration } from "@rhs-ui/marketing/video-testimonials/duration";
import type { TestimonialVideo, VideoTestimonialsLabels } from "@rhs-ui/marketing/video-testimonials/types";
import { VideoCard } from "@rhs-ui/marketing/video-testimonials/video-card";
import { cn } from "@/lib/utils";

export type { TestimonialVideo, TestimonialVideoCaptions, VideoTestimonialsLabels } from "@rhs-ui/marketing/video-testimonials/types";

export interface VideoTestimonialsProps extends Omit<ComponentProps<"section">, "title" | "children"> {
  /** One to four customers on camera; three is the grid this is made for. */
  videos: readonly TestimonialVideo[];
  /** The heading of the section. */
  title: string;
  /** One sentence under the title. */
  description?: string;
  /**
   * Renders the player for a video in place of the built-in video element, for an embed from your video host. It is
   * called for every card when the grid renders, but what it returns only mounts once that card has been pressed.
   * Fill the 16:9 frame it is given: `className="absolute inset-0 size-full"`.
   */
  renderPlayer?: (video: TestimonialVideo) => ReactNode;
  /** The locale the length is spoken in ("2 minutes 14 seconds"). Default "en-US". */
  locale?: string;
  /** Words for the fixed text, for a site that is not in English. */
  labels?: Partial<VideoTestimonialsLabels>;
}

const LABELS: VideoTestimonialsLabels = {
  play: "Play {name}'s story, {duration}",
  close: "Close video",
  hint: "A video with player controls. Press Escape to close it.",
  failed: "This video could not be loaded.",
  captions: "Captions",
};

/** The grid fits the number of cards: three across from 768px is the layout it is made for. */
const columnsFor = (count: number): string => (count <= 1 ? "mx-auto max-w-2xl" : count === 2 ? "sm:grid-cols-2" : count === 3 ? "md:grid-cols-3" : "sm:grid-cols-2 lg:grid-cols-4");

/**
 * Customers on camera, with nothing loaded until someone asks. Each card is
 * one real button: a poster that is always visible (never revealed by an
 * animation), a play disc, the person's name and role and the length as text,
 * named like "Play Maria's story, 2 minutes 14 seconds". Pressing it opens a
 * dialog with a native video (controls, no preload, a captions track when you
 * give one) and starts it; closing the dialog pauses the video and returns focus
 * to the card, and Escape closes it. Hosting the video elsewhere? `renderPlayer`
 * puts your embed in the same dialog and mounts it only when the card is
 * pressed. A page of three customers' faces and voices costs the poster images
 * and nothing more.
 */
export function VideoTestimonials({ videos, title, description, renderPlayer, locale = "en-US", labels, className, ...props }: VideoTestimonialsProps) {
  const words = { ...LABELS, ...labels };
  const heading = useId();

  return (
    <section data-slot="video-testimonials" aria-labelledby={heading} className={cn("py-16 sm:py-24", className)} {...props}>
      <header className="mx-auto max-w-2xl text-center">
        <h2 id={heading} className="text-3xl font-medium tracking-[-0.04em] text-balance sm:text-4xl">
          {title}
        </h2>
        {description ? <p className="mt-3 text-base leading-relaxed text-pretty text-muted-foreground">{description}</p> : null}
      </header>
      <ul role="list" className={cn("mt-12 grid gap-x-6 gap-y-10 sm:mt-16", columnsFor(videos.length))}>
        {videos.map((video) => (
          <li key={video.id} className="min-w-0">
            <VideoCard
              video={video}
              playLabel={words.play.replace("{name}", video.name).replace("{duration}", spokenDuration(video.duration, locale))}
              closeLabel={words.close}
              hintLabel={words.hint}
              failedLabel={words.failed}
              captionsLabel={words.captions}
            >
              {renderPlayer ? renderPlayer(video) : null}
            </VideoCard>
          </li>
        ))}
      </ul>
    </section>
  );
}

"use client";

import { useId, useRef, useState, type ReactNode } from "react";

import { IconClose, IconPlay } from "@rhs-ui/icons";
import type { TestimonialVideo } from "@rhs-ui/marketing/video-testimonials/types";
import { Button } from "@rhs-ui/primitives/button";
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogTitle, DialogTrigger } from "@rhs-ui/primitives/dialog";

export interface VideoCardProps {
  video: TestimonialVideo;
  /** The name of the card's button, already spelled out: "Play Maria's story, 2 minutes 14 seconds". */
  playLabel: string;
  /** The name of the dialog's close button. */
  closeLabel: string;
  /** What the dialog says about itself to a screen reader. */
  hintLabel: string;
  /** Shown over the player when the video cannot be loaded. */
  failedLabel: string;
  /** The name of a captions track that has no label of its own. */
  captionsLabel: string;
  /** The player from `renderPlayer`. When there is one it takes the place of the video element. */
  children?: ReactNode;
}

/** "Maria Alvarez" is "MA": the card's stand-in when the poster is missing or broken. */
const monogram = (name: string): string => {
  const words = name.trim().split(/\s+/).filter(Boolean);
  return ((words[0]?.[0] ?? "") + (words.length > 1 ? (words[words.length - 1]?.[0] ?? "") : "")).toUpperCase();
};

/**
 * One customer on camera: a poster that is always visible, the person's name
 * and role, and the length, all one button. Pressing it opens a dialog with
 * the video (or your own player) and starts it; closing the dialog stops the
 * video and puts focus back on the card. Nothing about the video is fetched
 * before that press.
 */
export function VideoCard({ video, playLabel, closeLabel, hintLabel, failedLabel, captionsLabel, children }: VideoCardProps) {
  const [open, setOpen] = useState(false);
  const [posterBroken, setPosterBroken] = useState(false);
  const [failed, setFailed] = useState(false);
  const player = useRef<HTMLVideoElement>(null);
  const roleId = useId();
  const embed = children !== undefined && children !== null;
  const playable = Boolean(video.src) || embed;

  const change = (next: boolean) => {
    // Stop the sound at once: the dialog fades out for a moment before it leaves the page.
    if (!next) player.current?.pause();
    setFailed(false);
    setOpen(next);
  };

  return (
    <Dialog open={open} onOpenChange={change}>
      <DialogTrigger asChild>
        <button type="button" disabled={!playable} aria-describedby={roleId} className="group/card block w-full cursor-pointer text-left outline-none disabled:cursor-not-allowed disabled:opacity-60">
          <span className="sr-only">{playLabel}</span>
          <span aria-hidden="true" className="relative block aspect-video overflow-hidden rounded-xl border border-border bg-muted transition-shadow duration-150 group-focus-visible/card:ring-[3px] group-focus-visible/card:ring-ring/40 motion-reduce:transition-none">
            {video.poster && !posterBroken ? (
              <img
                src={video.poster}
                alt=""
                loading="lazy"
                decoding="async"
                draggable={false}
                onError={() => setPosterBroken(true)}
                className="absolute inset-0 size-full object-cover transition-transform duration-500 ease-out motion-safe:group-hover/card:scale-[1.03] motion-reduce:transition-none"
              />
            ) : (
              // The initials sit in a small tile in the corner, like an avatar: the play disc owns the middle of the frame.
              <span className="absolute top-3 left-3 grid size-10 place-items-center rounded-lg border border-border bg-background text-sm font-medium tracking-[-0.01em] text-muted-foreground select-none">
                {monogram(video.name)}
              </span>
            )}
            {/* The ring is the disc's own edge, in the opposite tone, so it holds on a poster of any colour. */}
            <span
              className="absolute top-1/2 left-1/2 grid size-14 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-foreground text-background shadow-sm ring-2 ring-background/80 transition-transform duration-200 motion-safe:group-hover/card:scale-110 motion-reduce:transition-none"
            >
              <IconPlay className="size-6 translate-x-px fill-current" />
            </span>
            <span className="absolute right-3 bottom-3 rounded-md bg-foreground px-2 py-1 text-xs leading-none font-medium text-background tabular-nums">
              {video.duration}
            </span>
          </span>
          <span aria-hidden="true" className="mt-4 block">
            <span className="block text-base leading-snug font-medium tracking-[-0.01em] decoration-foreground/40 underline-offset-4 group-hover/card:underline">{video.name}</span>
            <span id={roleId} className="mt-0.5 block text-sm leading-snug text-muted-foreground">
              {video.role}
            </span>
          </span>
        </button>
      </DialogTrigger>
      <DialogContent
        showCloseButton={false}
        onOpenAutoFocus={(event) => {
          // A native video takes focus and starts: the press that opened the dialog is the reader asking for it. An embed keeps the default.
          const node = player.current;
          if (!node) return;
          event.preventDefault();
          node.focus();
          void node.play().catch(() => {});
        }}
        className="w-[min(56rem,calc(100vw_-_2rem),calc((100dvh_-_9rem)*16/9))] max-w-none grid-cols-[minmax(0,1fr)] gap-0 overflow-hidden p-0 sm:max-w-none"
      >
        <div className="flex min-w-0 items-center justify-between gap-4 border-b border-border py-2 pr-2 pl-4 sm:pl-5">
          <DialogTitle className="truncate text-sm">
            {video.name}
            <span className="font-normal text-muted-foreground">, {video.role}</span>
          </DialogTitle>
          <DialogClose asChild>
            <Button variant="ghost" size="icon-sm" aria-label={closeLabel}>
              <IconClose />
            </Button>
          </DialogClose>
        </div>
        <DialogDescription className="sr-only">{hintLabel}</DialogDescription>
        <div className="dark relative aspect-video bg-black text-foreground">
          {embed ? (
            children
          ) : (
            <video
              ref={player}
              src={video.src}
              poster={video.poster}
              controls
              playsInline
              preload="none"
              aria-label={`${video.name}, ${video.role}`}
              onError={() => setFailed(true)}
              className="absolute inset-0 size-full bg-black object-contain outline-none focus-visible:ring-[3px] focus-visible:ring-ring/60 focus-visible:ring-inset"
            >
              {video.captions ? <track kind="captions" src={video.captions.src} srcLang={video.captions.lang} label={video.captions.label ?? captionsLabel} default /> : null}
            </video>
          )}
          {failed ? (
            <div role="alert" className="absolute inset-0 grid place-content-center bg-black px-6 text-center text-sm text-foreground">
              {failedLabel}
            </div>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
}

export interface TestimonialVideoCaptions {
  /** The address of the WebVTT file. */
  src: string;
  /** The language of the captions as a BCP 47 tag: "en". */
  lang: string;
  /** The name the player shows for the track: "English". Falls back to the `captions` label. */
  label?: string;
}

export interface TestimonialVideo {
  /** Identifies the video in the grid. */
  id: string;
  /** The customer's name. It is the name of the card and of the dialog. */
  name: string;
  /** Their job and company: "Head of operations, Northwind". */
  role: string;
  /** A 16:9 picture of them, with open ground in the middle where the play button sits. It is always visible; without one, or when it cannot load, the card shows their initials in a small tile in the corner. */
  poster: string;
  /** The video file. Not fetched until the card is pressed. Leave it out when you pass `renderPlayer`. */
  src?: string;
  /** The length as people write it: "2:14", or "1:02:30" for an hour. It is shown on the card and spoken in full in the button's name. */
  duration: string;
  /** A captions track for the player, switched on when the video opens. */
  captions?: TestimonialVideoCaptions;
}

export interface VideoTestimonialsLabels {
  /** The name of a card's button; `{name}` and `{duration}` (spoken: "2 minutes 14 seconds") are filled in. Default "Play {name}'s story, {duration}". */
  play: string;
  /** The name of the close button of the dialog. Default "Close video". */
  close: string;
  /** What the dialog says about itself to a screen reader. Default "A video with player controls. Press Escape to close it.". */
  hint: string;
  /** Shown over the player when the video cannot be loaded. Default "This video could not be loaded.". */
  failed: string;
  /** The name of a captions track that has no `label`. Default "Captions". */
  captions: string;
}

/** "2:14" is 134 seconds and "1:02:30" is 3750. Anything else is NaN. */
export function secondsOf(duration: string): number {
  const parts = duration.trim().split(":");
  if (parts.length < 2 || parts.length > 3 || !parts.every((part) => /^\d{1,2}$/.test(part))) return Number.NaN;
  return parts.reduce((total, part) => total * 60 + Number(part), 0);
}

type Unit = "hour" | "minute" | "second";

/** One amount in one unit, in the reader's words: the names come from Intl, not from a list of ours. */
function unitText(amount: number, unit: Unit, locale: string): string {
  const options: Intl.NumberFormatOptions = { style: "unit", unit, unitDisplay: "long", maximumFractionDigits: 0 };
  try {
    return new Intl.NumberFormat(locale, options).format(amount);
  } catch {
    // A locale the browser does not know must not take the page down.
    return new Intl.NumberFormat("en-US", options).format(amount);
  }
}

/** "2:14" as it is spoken: "2 minutes 14 seconds". Text that is not a length is returned as it came. */
export function spokenDuration(duration: string, locale: string): string {
  const total = secondsOf(duration);
  if (Number.isNaN(total)) return duration;
  const amounts: readonly (readonly [Unit, number])[] = [
    ["hour", Math.floor(total / 3600)],
    ["minute", Math.floor((total % 3600) / 60)],
    ["second", total % 60],
  ];
  const parts = amounts.filter(([, amount]) => amount > 0).map(([unit, amount]) => unitText(amount, unit, locale));
  if (!parts.length) return unitText(0, "second", locale);
  try {
    return new Intl.ListFormat(locale, { style: "narrow", type: "unit" }).format(parts);
  } catch {
    return new Intl.ListFormat("en-US", { style: "narrow", type: "unit" }).format(parts);
  }
}
